            }
            HStack { Button("取消") { dismiss() }.keyboardShortcut(.cancelAction); Spacer(); if starting { ProgressView().controlSize(.small) }; Button("创建对话") {
                guard let agent = model.settings.agents.first(where: { $0.id == agentID }) else { return }
